"""Presenter-view HTML: countdown budget, teleprompter notes, dual slide
preview (current + next), synced to the deck over the same BroadcastChannel."""

import json


def build_presenter_html(*, title, deckname, notes_html_list, budget_min, sync_channel, fonts_css):
    budget_s = budget_min * 60
    notes_js = json.dumps(notes_html_list)
    return f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><title>Presenter View · {title}</title><style>{fonts_css}
*{{box-sizing:border-box;margin:0;padding:0}}body{{font-family:'Red Hat Text',system-ui,sans-serif;background:#0a0a0a;color:#ccc;height:100vh;overflow:hidden}}
.layout{{display:grid;grid-template-columns:3fr 1fr;grid-template-rows:auto 1fr auto;height:100vh}}
.topbar{{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;padding:8px 20px;background:#151515;border-bottom:2px solid #ee0000}}.topbar .title{{color:#ee0000;font-weight:700;font-size:15px}}.topbar .clock{{font-size:14px;color:#666;font-variant-numeric:tabular-nums;margin-right:18px}}.topbar .elapsed{{font-size:40px;font-weight:900;font-family:'Red Hat Display',sans-serif;color:#fff;font-variant-numeric:tabular-nums;letter-spacing:.02em}}.topbar .elapsed.warn{{color:#f0ab00}}.topbar .elapsed.crit{{color:#ee0000}}.topbar .budget{{font-size:13px;color:#777;margin-left:14px}}.topbar button{{background:#333;color:#ccc;border:1px solid #555;border-radius:4px;padding:3px 10px;margin-left:5px;cursor:pointer;font-size:11px}}
.preview-panel{{display:flex;flex-direction:column;padding:10px;gap:6px}}.preview-label{{font-size:10px;text-transform:uppercase;letter-spacing:.1em;color:#555;font-weight:600}}.preview-current{{flex:none;aspect-ratio:16/9;width:100%;border:2px solid #ee0000;border-radius:6px;overflow:hidden;background:#151515;position:relative}}.preview-next{{flex:none;aspect-ratio:16/9;width:100%;border:1px solid #333;border-radius:6px;overflow:hidden;background:#1a1a1a;position:relative}}.preview-current iframe,.preview-next iframe{{position:absolute;top:0;left:0;width:1920px;height:1080px;transform-origin:top left;border:none;pointer-events:none}}
.notes-panel{{padding:14px 22px;overflow-y:auto;border-right:2px solid #222;display:flex;flex-direction:column}}.slide-indicator{{font-size:12px;color:#777;margin-bottom:6px}}.notes-heading{{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:#ee0000;font-weight:700;margin-bottom:8px}}.notes-content{{font-size:20px;line-height:1.6;color:#ddd;flex:1;overflow-y:auto}}.notes-content .say{{color:#fff;margin:.4em 0}}.notes-content .do{{color:#f0ab00;font-family:'Red Hat Mono',monospace;font-size:.82em;line-height:1.5;margin:.5em 0 .5em 2.5em;padding-left:.9em;border-left:3px solid #f0ab00}}.notes-content .cue{{color:#8a949e;font-style:italic;font-size:.78em;line-height:1.5;margin:.5em 0 .5em 2.5em;padding-left:.9em;border-left:3px solid #333}}
.controls{{grid-column:1/-1;display:flex;gap:8px;align-items:center;padding:10px 20px;background:#151515;border-top:1px solid #333}}.controls button{{background:#ee0000;color:#fff;border:0;border-radius:4px;padding:8px 16px;cursor:pointer;font-weight:700}}.controls button.secondary{{background:#333;color:#ccc}}.controls .pos{{margin:0 10px;color:#aaa;font-variant-numeric:tabular-nums}}
</style></head><body><div class="layout">
<div class="topbar"><span class="title">PRESENTER VIEW · {title}</span><div style="display:flex;align-items:baseline"><span class="clock" id="clock"></span><span class="elapsed" id="elapsed">{budget_min:02d}:00</span><span class="budget">remaining of {budget_min:02d}:00 content · Q&amp;A after · yellow at 80%, red at 92%</span><button onclick="startTimer()">Start</button><button onclick="resetTimer()">Reset</button></div></div>
<div class="notes-panel"><div class="slide-indicator" id="slideIndicator"></div><div class="notes-heading">Speaker notes</div><div class="notes-content" id="notesContent"></div></div>
<div class="preview-panel"><span class="preview-label">Current slide</span><div class="preview-current"><iframe id="currentFrame" src="{deckname}?presenter=child"></iframe></div><span class="preview-label">Next slide</span><div class="preview-next"><iframe id="nextFrame" src="{deckname}?presenter=child"></iframe></div></div>
<div class="controls"><button class="secondary" onclick="go(0)">&#8676; First</button><button class="secondary" onclick="go(current-1)">&#8592; Prev</button><span class="pos" id="pos"></span><button onclick="go(current+1)">Next &#8594;</button><button class="secondary" onclick="go(totalSlides-1)">Last &#8677;</button></div>
</div><script>
function fitPreviews(){{for(const el of document.querySelectorAll('.preview-current,.preview-next')){{const f=el.querySelector('iframe');f.style.transform='scale('+(el.clientWidth/1920)+')';}}}}window.addEventListener('resize',fitPreviews);window.addEventListener('load',fitPreviews);setTimeout(fitPreviews,300);
const notes={notes_js};const totalSlides=notes.length;let current=0;const channel=new BroadcastChannel('{sync_channel}');let timerStart=null,timerInterval=null,auto=false;
function updateClock(){{document.getElementById('clock').textContent=new Date().toLocaleTimeString('en-US',{{hour:'2-digit',minute:'2-digit',second:'2-digit'}});}}
const BUDGET={budget_s};function fmt(s){{const n=Math.abs(s);return (s<0?'-':'')+String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0');}}function tick(){{const s=Math.floor((Date.now()-timerStart)/1000);const el=document.getElementById('elapsed');el.textContent=fmt(BUDGET-s);el.classList.toggle('warn',s>=BUDGET*0.8&&s<BUDGET*0.92);el.classList.toggle('crit',s>=BUDGET*0.92);}}function startTimer(){{if(timerInterval)return;timerStart=timerStart||Date.now();tick();timerInterval=setInterval(tick,1000);}}
function resetTimer(){{clearInterval(timerInterval);timerInterval=null;timerStart=null;const el=document.getElementById('elapsed');el.textContent=fmt(BUDGET);el.classList.remove('warn','crit');}}
function updateView(){{document.getElementById('slideIndicator').textContent='Slide '+(current+1)+' of '+totalSlides;document.getElementById('pos').textContent=(current+1)+' / '+totalSlides;document.getElementById('notesContent').innerHTML=notes[current];document.getElementById('currentFrame').contentWindow.postMessage({{showSlide:current}},'*');document.getElementById('nextFrame').contentWindow.postMessage({{showSlide:Math.min(current+1,totalSlides-1)}},'*');}}
function go(n){{if(n>0&&!timerInterval)startTimer();if(!auto&&n>0){{startTimer();auto=true;}}current=Math.max(0,Math.min(n,totalSlides-1));channel.postMessage({{slide:current}});updateView();}}
channel.onmessage=e=>{{if(typeof e.data.slide==='number'&&e.data.slide!==current){{current=e.data.slide;updateView();}}}};
document.addEventListener('keydown',e=>{{if(e.key==='ArrowRight'||e.key==='ArrowDown'||e.key===' '){{e.preventDefault();go(current+1);}}if(e.key==='ArrowLeft'||e.key==='ArrowUp'){{e.preventDefault();go(current-1);}}if(e.key==='Home'){{e.preventDefault();go(0);}}if(e.key==='End'){{e.preventDefault();go(totalSlides-1);}}}});
setInterval(updateClock,1000);updateClock();window.addEventListener('load',updateView);
</script></body></html>"""
